-- Keep the DB-first lesson quiz catalog aligned with the reviewed Grade 8 content.
insert into public.quiz_questions (
  id, topic, question, question_bg, options, options_bg, correct_index, explanation, explanation_bg
)
values
  ('html-1', 'html', 'Which element is best for a self-contained piece of content?', 'Кой елемент е най-подходящ за самостоятелна част от съдържание?', '["<div>","<article>","<span>","<b>"]'::jsonb, '["<div>","<article>","<span>","<b>"]'::jsonb, 1, 'article groups independent content like cards or posts.', 'article групира самостоятелно съдържание като карти или постове.'),
  ('html-2', 'html', 'What does semantic HTML improve?', 'Какво подобрява семантичният HTML?', '["Only colors","Accessibility and structure","Database speed","Git commits"]'::jsonb, '["Само цветовете","Достъпност и структура","Скорост на базата","Git commits"]'::jsonb, 1, 'Semantic tags help screen readers and make layouts easier to reason about.', 'Семантичните тагове помагат на screen readers и правят layout-а по-ясен.'),
  ('html-3', 'html', 'Which explicit button type submits a form?', 'Кой изрично зададен тип бутон изпраща формуляр?', '["type=\"reset\"","type=\"button\"","type=\"submit\"","type=\"menu\""]'::jsonb, '["type=\"reset\"","type=\"button\"","type=\"submit\"","type=\"menu\""]'::jsonb, 2, 'type="submit" clearly states that the button submits the form.', 'type="submit" ясно задава, че бутонът изпраща формуляра.'),
  ('css-1', 'css', 'Which property creates space inside an element?', 'Кое свойство създава пространство вътре в елемент?', '["margin","padding","border-radius","z-index"]'::jsonb, '["margin","padding","border-radius","z-index"]'::jsonb, 1, 'Padding adds inner space; margin adds outer space.', 'Padding добавя вътрешно пространство; margin — външно.'),
  ('css-2', 'css', 'Which declaration creates two equal grid columns?', 'Коя декларация създава две еднакво широки колони в CSS Grid?', '["grid-template-columns: 1fr 1fr","grid-template-rows: 1fr 1fr","text-align: center","position: fixed"]'::jsonb, '["grid-template-columns: 1fr 1fr","grid-template-rows: 1fr 1fr","text-align: center","position: fixed"]'::jsonb, 0, 'Two 1fr tracks divide the available horizontal space equally.', 'Две колони по 1fr разделят наличното хоризонтално пространство поравно.'),
  ('css-3', 'css', 'What does border-radius change?', 'Какво променя border-radius?', '["Text color","Corner roundness","Font size","Line height"]'::jsonb, '["Цвета на текста","Заобленост на ъглите","Размера на шрифта","Височина на реда"]'::jsonb, 1, 'border-radius rounds the corners of a box.', 'border-radius заобля ъглите на box.'),
  ('js-1', 'javascript', 'Which keyword should you prefer for values that do not change?', 'Коя дума е по-добра за стойности, които не се променят?', '["var","let","const","static"]'::jsonb, '["var","let","const","static"]'::jsonb, 2, 'const prevents reassignment and makes intent clearer.', 'const спира повторно присвояване и прави кода по-ясен.'),
  ('js-2', 'javascript', 'What does a function return if there is no return statement?', 'Какво връща функция без return?', '["0","null","undefined","false"]'::jsonb, '["0","null","undefined","false"]'::jsonb, 2, 'JavaScript functions return undefined by default.', 'JavaScript функциите връщат undefined по подразбиране.'),
  ('js-3', 'javascript', 'Which method adds one item to the end of an array?', 'Кой метод добавя един елемент в края на масив?', '["push()","pop()","shift()","slice()"]'::jsonb, '["push()","pop()","shift()","slice()"]'::jsonb, 0, 'push() mutates the array and returns the new length.', 'push() променя масива и връща новата дължина.'),
  ('dom-1', 'dom', 'Which API listens for user clicks?', 'Кой API слуша за кликове на потребителя?', '["addEventListener(''click'')","querySelector(''click'')","JSON.parse()","fetch()"]'::jsonb, '["addEventListener(''click'')","querySelector(''click'')","JSON.parse()","fetch()"]'::jsonb, 0, 'Event listeners connect user actions to your JavaScript logic.', 'Event listeners свързват действията на потребителя с JavaScript логиката.'),
  ('dom-2', 'dom', 'What does document.querySelector(''.card'') return?', 'Какво връща document.querySelector(''.card'')?', '["All matching elements","The first matching element, or null","A CSS file","The last click event"]'::jsonb, '["Всички съвпадащи елементи","Първия съвпадащ елемент или null","CSS файл","Последното събитие click"]'::jsonb, 1, 'querySelector returns the first match for a CSS selector, or null when nothing matches.', 'querySelector връща първото съвпадение за CSS селектор или null, когато няма такова.'),
  ('dom-3', 'dom', 'A form field contains invalid data. What is the clearest response?', 'Поле във формуляр съдържа невалидни данни. Коя реакция е най-ясна?', '["Ignore the input","Delete the whole form","Show a specific message next to the field and keep the entered value","Reload without explanation"]'::jsonb, '["Да се игнорира въведеното","Да се изтрие целият формуляр","Да се покаже конкретно съобщение до полето и да се запази въведеното","Да се презареди без обяснение"]'::jsonb, 2, 'A nearby, specific message helps the user identify and correct the problem.', 'Конкретно съобщение до полето помага на потребителя да открие и поправи проблема.'),
  ('fetch-1', 'fetch', 'What does fetch() return?', 'Какво връща fetch()?', '["JSON directly","A Promise","An array","A DOM node"]'::jsonb, '["JSON директно","Promise","Масив","DOM node"]'::jsonb, 1, 'fetch resolves to a Response object after the network request.', 'fetch връща Response обект след мрежовата заявка.'),
  ('fetch-2', 'fetch', 'Which HTTP method is commonly used to create data?', 'Кой HTTP метод се ползва най-често за създаване на данни?', '["GET","POST","DELETE","OPTIONS"]'::jsonb, '["GET","POST","DELETE","OPTIONS"]'::jsonb, 1, 'POST sends a body to create or submit new data.', 'POST изпраща body за създаване или изпращане на нови данни.'),
  ('fetch-3', 'fetch', 'What should an interface do when a network request fails?', 'Какво трябва да направи интерфейсът, когато мрежова заявка е неуспешна?', '["Pretend the data was saved","Show a clear error and offer a safe retry","Erase all local work","Keep loading forever"]'::jsonb, '["Да се престори, че данните са записани","Да покаже ясна грешка и безопасна възможност за нов опит","Да изтрие цялата локална работа","Да зарежда безкрайно"]'::jsonb, 1, 'Clear feedback and a controlled retry help the user recover without losing work.', 'Ясната обратна връзка и контролиран нов опит помагат без загуба на работа.'),
  ('react-1', 'react', 'What is a React component?', 'Какво е React component?', '["A database table","A reusable UI function","A CSS file","A Git branch"]'::jsonb, '["Таблица в база","Преизползваема UI функция","CSS файл","Git branch"]'::jsonb, 1, 'Components let you split UI into reusable pieces with props and state.', 'Components разделят UI на преизползваеми части с props и state.'),
  ('react-2', 'react', 'How do you pass data into a child component?', 'Как подаваш данни към child component?', '["With props","With SQL","With padding","With return only"]'::jsonb, '["С props","С SQL","С padding","Само с return"]'::jsonb, 0, 'Props are the standard way to pass read-only data into components.', 'Props са стандартният начин да подадеш read-only данни към components.'),
  ('react-3', 'react', 'When should state be used in an interface component?', 'Кога е подходящо да се използва state в компонент на интерфейса?', '["For a value that changes after user interaction","For a fixed heading that never changes","To replace every CSS rule","To store a private server key"]'::jsonb, '["За стойност, която се променя след действие на потребителя","За постоянно заглавие, което не се променя","За замяна на всяко CSS правило","За съхраняване на таен сървърен ключ"]'::jsonb, 0, 'State represents data that can change and should cause the component to update.', 'State представя данни, които се променят и трябва да обновят компонента.'),
  ('api-1', 'api', 'What makes an API response easier for a client to use safely?', 'Какво прави отговора на API по-лесен за безопасно използване от клиента?', '["A consistent data and error structure","A different field name on every request","Secrets included for debugging","Success status for every error"]'::jsonb, '["Постоянна структура за данни и грешки","Различно име на полето при всяка заявка","Включени тайни за отстраняване на грешки","Успешен статус за всяка грешка"]'::jsonb, 0, 'A consistent contract lets the client validate data and handle failures predictably.', 'Постоянният формат позволява на клиента да проверява данните и да обработва грешките предвидимо.'),
  ('api-2', 'api', 'Which HTTP status code fits a missing required field?', 'Кой HTTP status code е подходящ за липсващо задължително поле?', '["200","400","404","500"]'::jsonb, '["200","400","404","500"]'::jsonb, 1, '400 Bad Request tells the client the input was invalid.', '400 Bad Request казва на клиента, че входът е невалиден.'),
  ('api-3', 'api', 'Where should a private API key be stored in a web application?', 'Къде трябва да се съхранява частен API ключ в уеб приложение?', '["In browser code","In a public repository","In protected server-side configuration","In an image file"]'::jsonb, '["В кода на браузъра","В публично хранилище","В защитена сървърна конфигурация","Във файл с изображение"]'::jsonb, 2, 'Private keys must remain on the server and must not be sent to the browser or committed publicly.', 'Частните ключове трябва да останат на сървъра и да не се изпращат към браузъра или публично хранилище.'),
  ('api-4', 'api', 'What status should a protected API endpoint return when authentication is missing?', 'Какъв статус трябва да върне защитена API крайна точка, когато липсва удостоверяване?', '["200 with empty body","401 Unauthorized","302 to homepage","500"]'::jsonb, '["200 с празно body","401 Unauthorized","302 към homepage","500"]'::jsonb, 1, '401 clearly signals that authentication is required.', '401 ясно показва, че е нужна автентикация.'),
  ('api-5', 'api', 'What should a server do before saving data received from a client?', 'Какво трябва да направи сървърът, преди да запише данни, получени от клиент?', '["Trust every field","Validate type, range, length, and permission","Remove all error messages","Save the data twice"]'::jsonb, '["Да се довери на всяко поле","Да провери тип, диапазон, дължина и право за действие","Да премахне всички съобщения за грешки","Да запише данните два пъти"]'::jsonb, 1, 'Server-side validation protects data even when browser checks are bypassed.', 'Сървърната проверка защитава данните дори когато проверките в браузъра са заобиколени.'),
  ('quiz-gen-1', 'quiz-generator', 'What input does a quiz generator need at minimum?', 'Какво трябва да има генераторът за въпроси като минимум?', '["A learning objective and a reviewed question bank","Only a timer and a title","Only the correct answers","A list of student passwords"]'::jsonb, '["Учебна цел и проверена банка от въпроси","Само таймер и заглавие","Само верните отговори","Списък с пароли на ученици"]'::jsonb, 0, 'Questions should measure a stated learning objective and be reviewed for correctness and clarity.', 'Въпросите трябва да измерват заявена учебна цел и да са проверени за вярност и яснота.'),
  ('quiz-gen-2', 'quiz-generator', 'Why should a quiz store an explanation with the correct answer?', 'Защо тестът трябва да пази обяснение към верния отговор?', '["To give useful feedback after an attempt","To make every answer look correct","To replace the question","To reveal student passwords"]'::jsonb, '["За да даде полезна обратна връзка след опита","За да изглежда всеки отговор верен","За да замени въпроса","За да разкрива пароли на ученици"]'::jsonb, 0, 'An explanation helps the learner understand the reasoning instead of seeing only a score.', 'Обяснението помага на ученика да разбере логиката, вместо да вижда само резултат.'),
  ('quiz-gen-3', 'quiz-generator', 'Which question is the fairest knowledge check?', 'Кой въпрос е най-подходящ за справедлива проверка на знанията?', '["A clear question linked to a taught objective with one defensible answer","A trick question on an untaught detail","A question with two equally correct answers","A question whose wording reveals the answer"]'::jsonb, '["Ясен въпрос по изучавана цел с един защитим верен отговор","Подвеждащ въпрос за непреподаван детайл","Въпрос с два еднакво верни отговора","Въпрос, чиято формулировка подсказва отговора"]'::jsonb, 0, 'A fair item measures what was taught, uses clear language, and has one unambiguous answer.', 'Справедливият въпрос измерва преподаваното, използва ясен език и има един недвусмислен отговор.'),
  ('fullstack-1', 'fullstack', 'Which sequence best describes submitting data in a full-stack application?', 'Коя последователност най-добре описва изпращането на данни в пълно уеб приложение?', '["Interface → server validation → database → response","Database → CSS → keyboard → response","Interface → public secret → database → no response","Browser → printer → database → image"]'::jsonb, '["Интерфейс → сървърна проверка → база данни → отговор","База данни → CSS → клавиатура → отговор","Интерфейс → публична тайна → база данни → без отговор","Браузър → принтер → база данни → изображение"]'::jsonb, 0, 'The client sends input, the server validates and stores it, then returns a clear result.', 'Клиентът изпраща данните, сървърът ги проверява и записва, след което връща ясен резултат.'),
  ('fullstack-2', 'fullstack', 'Which information must not be stored as plain text in browser local storage?', 'Коя информация не трябва да се съхранява като обикновен текст в локалното хранилище на браузъра?', '["A selected color theme","An unfinished filter choice","Passwords and private API keys","The current page number"]'::jsonb, '["Избраната цветова тема","Недовършен избор на филтър","Пароли и частни API ключове","Номерът на текущата страница"]'::jsonb, 2, 'Browser storage is accessible to page scripts and is not a safe vault for passwords or private keys.', 'Локалното хранилище е достъпно за скриптовете на страницата и не е безопасно място за пароли или частни ключове.'),
  ('fullstack-3', 'fullstack', 'Which page should require an authenticated user?', 'Коя страница трябва да изисква удостоверен потребител?', '["A public school homepage","A personal page with grades and progress","A public contact page","A sign-in page"]'::jsonb, '["Публична начална страница на училище","Лична страница с оценки и напредък","Публична страница за контакт","Страница за вход"]'::jsonb, 1, 'Personal educational data should be available only to authorized users.', 'Личните образователни данни трябва да са достъпни само за упълномощени потребители.'),
  ('ai-1', 'ai', 'What is the main difference between a fixed rule and a learned model?', 'Каква е основната разлика между зададено правило и научен модел?', '["A rule is written directly, while a model finds patterns from examples","A model is always correct","A rule requires more training data","There is no difference"]'::jsonb, '["Правилото се задава пряко, а моделът открива закономерности от примери","Моделът винаги е верен","Правилото изисква повече обучаващи данни","Няма разлика"]'::jsonb, 0, 'Rules are specified by people; learned models are fitted from data and can still make mistakes.', 'Правилата се задават от хора, а научените модели се настройват по данни и могат да грешат.'),
  ('ai-2', 'ai', 'What should not be included in a prompt sent to a public AI service?', 'Какво не трябва да се включва в заявка към публична AI услуга?', '["A general topic","An invented example","Passwords, personal data, or confidential documents","The desired answer format"]'::jsonb, '["Обща тема","Измислен пример","Пароли, лични данни или поверителни документи","Желаният формат на отговора"]'::jsonb, 2, 'Sensitive data may be processed outside the school''s control and should not be shared without authorization.', 'Чувствителните данни може да се обработват извън контрола на училището и не трябва да се споделят без разрешение.'),
  ('ai-3', 'ai', 'An AI answer sounds confident but gives no sources. What should you do?', 'Отговор от AI звучи уверено, но няма източници. Какво трябва да направиш?', '["Submit it as a proven fact","Verify its claims with reliable independent sources","Add personal data to improve it","Remove any conflicting evidence"]'::jsonb, '["Да го предадеш като доказан факт","Да провериш твърденията в надеждни независими източници","Да добавиш лични данни, за да го подобриш","Да премахнеш всяко противоречащо доказателство"]'::jsonb, 1, 'A confident tone does not guarantee accuracy; the learner remains responsible for verification.', 'Увереният тон не гарантира вярност; ученикът остава отговорен за проверката.'),
  ('mobile-1', 'mobile', 'Which button height is the easiest practical target to tap among these options?', 'Коя от тези височини е най-практична за лесно натискане на бутон?', '["12px","24px","32px","48px"]'::jsonb, '["12px","24px","32px","48px"]'::jsonb, 3, 'Around 44–48 CSS pixels is a common practical target for comfortable touch interaction.', 'Около 44–48 CSS пиксела е честа практическа цел за удобно взаимодействие чрез докосване.'),
  ('mobile-2', 'mobile', 'What does width=device-width do?', 'Какво прави width=device-width?', '["Makes every element 100 pixels wide","Matches the layout viewport to the device width","Forces landscape mode","Disables page zoom by itself"]'::jsonb, '["Прави всеки елемент широк 100 пиксела","Съпоставя ширината на оформлението с ширината на устройството","Налага хоризонтален режим","Самостоятелно забранява увеличаването"]'::jsonb, 1, 'It prevents mobile browsers from rendering a tiny scaled desktop page.', 'Предотвратява показването на умалена настолна страница в мобилен браузър.'),
  ('mobile-3', 'mobile', 'How should a row of wide content cards usually adapt to a narrow phone screen?', 'Как обикновено трябва да се адаптира ред от широки карти към тесен телефонен екран?', '["Keep five narrow columns","Stack cards in one readable column","Hide all card text","Require sideways scrolling for the whole page"]'::jsonb, '["Да запази пет тесни колони","Да подреди картите в една четима колона","Да скрие целия текст в картите","Да изисква странично превъртане на цялата страница"]'::jsonb, 1, 'A single-column stack preserves readable content and avoids page-level horizontal scrolling.', 'Една колона запазва съдържанието четимо и избягва хоризонталното превъртане на страницата.'),
  ('product-1', 'product', 'What is the main purpose of a first prototype?', 'Каква е основната цел на първия прототип?', '["To include every planned feature","To test the riskiest assumption quickly with users","To avoid feedback until launch","To look finished even if it cannot be used"]'::jsonb, '["Да съдържа всяка планирана функция","Бързо да провери най-рисковото допускане с потребители","Да избегне обратна връзка до пускането","Да изглежда завършен, дори да не може да се използва"]'::jsonb, 1, 'A prototype is a quick, low-cost way to learn whether an idea solves the intended problem.', 'Прототипът е бърз и евтин начин да се провери дали идеята решава поставения проблем.'),
  ('product-2', 'product', 'Which interview question is most useful when researching a user problem?', 'Кой въпрос е най-полезен при проучване на потребителски проблем?', '["Our idea is great, isn''t it?","Tell me about the last time you faced this problem","Would you buy every feature we add?","Why do you dislike our design?"]'::jsonb, '["Нашата идея е страхотна, нали?","Разкажи ми за последния път, когато срещна този проблем","Би ли купил всяка функция, която добавим?","Защо не харесваш нашия дизайн?"]'::jsonb, 1, 'A neutral question about real past behavior produces more reliable evidence than a leading question.', 'Неутралният въпрос за реално минало поведение дава по-надеждни данни от подвеждащ въпрос.'),
  ('product-3', 'product', 'Which is the strongest evidence that a prototype is useful?', 'Кое е най-силното доказателство, че прототипът е полезен?', '["The team says it is excellent","Relevant users complete the main task and explain the benefit","The presentation has many slides","The logo uses a fashionable color"]'::jsonb, '["Екипът казва, че е отличен","Подходящи потребители изпълняват основната задача и обясняват ползата","Презентацията има много слайдове","Логото използва модерен цвят"]'::jsonb, 1, 'Observed behavior from target users is stronger evidence than the creators'' opinion or visual polish.', 'Наблюдаваното поведение на целеви потребители е по-силно доказателство от мнението на създателите или добрия външен вид.')
on conflict (id) do update set
  topic = excluded.topic,
  question = excluded.question,
  question_bg = excluded.question_bg,
  options = excluded.options,
  options_bg = excluded.options_bg,
  correct_index = excluded.correct_index,
  explanation = excluded.explanation,
  explanation_bg = excluded.explanation_bg;
